import { test, expect } from '@playwright/test';

test.describe('Locked Out User Login', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should remain on login page when locked out user tries to log in', async ({ page }) => {
    await page.fill('input[name="user-name"]', 'locked_out_user');
    await page.fill('input[name="password"]', 'secret_sauce');
    await page.click('input[type="submit"]');

    const errorContainer = await page.getByTestId('error');
    await expect(errorContainer).toBeVisible();
  });

  test('should display correct error message for locked out user', async ({ page }) => {
    await page.fill('input[name="user-name"]', 'locked_out_user');
    await page.fill('input[name="password"]', 'secret_sauce');
    await page.click('input[type="submit"]');

    const errorContainer = await page.getByTestId('error');
    await expect(errorContainer).toHaveText(/Sorry, this user has been locked out/);
  });
});
